// Some portions generated by Claude

// A SPARQL Update the server cannot parse is shown as the Query page shows a query it cannot parse: the position in
// the title, the parser's message in words, Go to line, and the message as written under Parser details.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');
const { createFormBrowserHarness } = require('./form-browser-harness.js');

const scripts = require('./workbench-scripts.js').compiledScriptsDir();

function loadWorkbench() {
    const workbench = {};
    const window = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, window, workbench, setTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), context, { filename });
    }
    window.workbench = context.workbench;
    return { workbench: context.workbench, window };
}

function runtime() {
    return {
        nothing: '',
        html(strings, ...values) { return { strings: Array.from(strings), values }; },
        render(template, mount) { mount.template = template; }
    };
}

/** The template as markup; event bindings (functions) are kept so a test can call them. */
function flatten(template, handlers) {
    if (Array.isArray(template)) {
        return template.map(entry => flatten(entry, handlers)).join('');
    }
    if (template && Array.isArray(template.strings)) {
        return template.strings.reduce((result, fragment, index) => {
            if (index >= template.values.length) {
                return result + fragment;
            }
            const value = template.values[index];
            if (typeof value === 'function') {
                handlers.push(value);
                return result + fragment + 'handler-' + (handlers.length - 1);
            }
            return result + fragment + flatten(value, handlers);
        }, '');
    }
    return template === null || typeof template === 'undefined' ? '' : String(template);
}

const context = { basePath: '/workbench', repositoryId: 'repo-1', workbench: { id: 'repo-1', readable: true, writeable: true } };

function updatePage(workbench, message) {
    const model = { viewId: 'update', vars: ['error-message', 'update'], rows: [], metadata: {} };
    model.rows = [[message, 'DELETE WHERE { ?s ?p }']];
    model.rowCount = 1;
    const handlers = [];
    const markup = flatten(workbench.views.pageTemplate(model, context, runtime()), handlers);
    const start = markup.indexOf('id="updateString.errors"');
    assert.ok(start >= 0, 'the error is the page\'s updateString.errors callout');
    // The callout ends where the editor field starts.
    return { callout: markup.substring(markup.lastIndexOf('<div', start), markup.indexOf('id="update-editor"', start)),
        handlers };
}

test('an Update syntax error names its position and its token, with Go to line and the parser details', () => {
    const { workbench, window } = loadWorkbench();
    const message = 'Encountered " "}" "} "" at line 1, column 22.\nWas expecting one of:\n    "." ...';
    const { callout, handlers } = updatePage(workbench, message);
    assert.match(callout, /class="workbench-callout workbench-callout--error" role="alert"/);
    assert.match(callout, /<strong class="workbench-callout__title">Syntax error on line 1, column 22<\/strong>/);
    assert.match(callout, /class="query-result-error__message">Unexpected "}"\. Expected "\."\.</);
    assert.match(callout, /<details class="query-result-error__details"><summary>Parser details<\/summary><pre>/);
    assert.ok(callout.includes(message), 'the parser details keep the message as written');
    const goTo = /<button[^>]*class="query-result-error__goto[^"]*"[^>]*@click=handler-(\d+)[^>]*>Go to line 1<\/button>/
        .exec(callout);
    assert.ok(goTo, 'Go to line is a button');
    const revealed = [];
    window.workbench.update = { showErrorLocation: (...location) => revealed.push(location) };
    handlers[Number(goTo[1])]();
    assert.deepEqual(revealed, [[1, 22, true]], 'Go to line shows the position in the editor');
});

test('an Update that ends too early says so of the update', () => {
    const { workbench } = loadWorkbench();
    const { callout } = updatePage(workbench, 'Encountered "<EOF>" at line 1, column 16.\nWas expecting:\n    "}" ...');
    assert.match(callout, /class="query-result-error__message">The update ends too early\. Expected "}"\.</);
});

test('an Update error without a position stays a plain error callout', () => {
    const { workbench } = loadWorkbench();
    const { callout } = updatePage(workbench, 'Repository is read-only');
    assert.match(callout, /Repository is read-only/);
    assert.doesNotMatch(callout, /Syntax error|Go to line|Parser details/);
});

test('the Update editor marks and reveals the reported line, and forgets it when the text changes', () => {
    const harness = createFormBrowserHarness({ globals: { namespaces: {} } });
    const page = harness.registerElement('div', { id: 'page' });
    page.appendChild(harness.registerElement('textarea', { id: 'update', value: 'DELETE WHERE {\n  ?s ?p\n}' }));
    harness.document.body.appendChild(page);
    const calls = [];
    const handlers = {};
    harness.context.YASQE = {
        defaults: {},
        Autocompleters: { prefixes: {} },
        registerAutocompleter() {},
        fromTextArea(textarea) {
            let value = textarea.value;
            return {
                getValue: () => value,
                setValue: (next) => { value = next; },
                refresh() {},
                save() {},
                focus() { calls.push('focus'); },
                getWrapperElement: () => harness.registerElement('div'),
                on(name, handler) { handlers[name] = handler; },
                getOption: () => false,
                setOption() {},
                getDoc: () => ({ lineCount: () => 3, setCursor: (position) => calls.push(['cursor', position.line, position.ch]) }),
                setGutterMarker: (line, gutter, marker) => calls.push(['gutter', line, gutter, marker ? marker.className : null]),
                addLineClass: (line, where, name) => calls.push(['addLineClass', line, where, name]),
                removeLineClass: (line, where, name) => calls.push(['removeLineClass', line, where, name]),
                scrollIntoView() { calls.push('scroll'); },
                toTextArea() {}
            };
        }
    };
    harness.loadScripts(['yasqeHelper.js', 'update.js']);
    harness.context.workbench.update.mount(page);
    harness.context.workbench.update.showErrorLocation(2, 5, true);
    assert.deepEqual(JSON.parse(JSON.stringify(calls)), [
        ['gutter', 1, 'gutterErrorBar', 'query-editor-error-marker'],
        ['addLineClass', 1, 'background', 'query-editor-error-line'],
        'focus', ['cursor', 1, 4], 'scroll'
    ]);
    calls.length = 0;
    handlers.change();
    assert.deepEqual(JSON.parse(JSON.stringify(calls)), [
        ['gutter', 1, 'gutterErrorBar', null],
        ['removeLineClass', 1, 'background', 'query-editor-error-line']
    ], 'editing the update removes the mark');
});
